<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\{User,Role};use App\Services\CredentialService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CredentialController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('credentials.view'),403);}
private function generateOk(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('credentials.generate'),403);}
private function canReset(Request $r,User $target):bool{$me=$r->user();if($me->isSuperAdmin()||$me->hasRole('admin'))return true;if($me->hasRole('head_academic'))return (bool)($target->student_id||$target->teacher_id);if(!$target->student_id||!$me->hasRole('curator')||!$me->teacher_id)return false;return DB::table('students as s')->join('study_groups as g','g.id','=','s.current_group_id')->where('s.id',$target->student_id)->where('g.curator_teacher_id',$me->teacher_id)->exists();}
public function index(Request $r,CredentialService $c){$this->view($r);$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$q=User::with('roles')->orderBy('name');if($r->filled('group'))$q->whereIn('student_id',DB::table('students')->where('current_group_id',$r->integer('group'))->pluck('id'));$users=$q->paginate(50)->withQueryString();foreach($users as $u)$u->plain_password=$c->reveal($u->password_encrypted);return view('admin.credentials.index',compact('users','groups'));}
public function generate(Request $r,CredentialService $c){$this->generateOk($r);$d=$r->validate(['group_id'=>'required|exists:study_groups,id','regenerate'=>'nullable|boolean']);$role=Role::where('code','student')->firstOrFail();$students=DB::table('students')->where('current_group_id',$d['group_id'])->where('status','active')->orderBy('last_name')->orderBy('first_name')->get();$count=0;foreach($students as $s){$u=User::where('student_id',$s->id)->first();if($u&&!$r->boolean('regenerate')&&$u->password_encrypted)continue;$login=$u?($u->login?:$c->login($s->last_name,$s->first_name,$s->id)):$c->login($s->last_name,$s->first_name,$s->id);$plain=$c->password();$data=$c->pack($plain)+['name'=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name),'login'=>$login,'email'=>($u&&$u->email)?$u->email:$login.'@students.local','student_id'=>$s->id,'is_active'=>true];if($u)$u->update($data);else $u=User::create($data);$u->roles()->syncWithoutDetaching([$role->id]);$count++;}return redirect()->route('admin.credentials.index',['group'=>$d['group_id']])->with('success','Создано/обновлено учётных записей: '.$count);}
private function canProvisionPerson(Request $r,string $kind,int $id):bool{$me=$r->user();if($me->isSuperAdmin()||$me->hasRole('admin')||$me->hasRole('head_academic'))return true;if($kind!=='student'||!$me->hasRole('curator')||!$me->teacher_id)return false;return DB::table('students as s')->join('study_groups as g','g.id','=','s.current_group_id')->where('s.id',$id)->where('g.curator_teacher_id',$me->teacher_id)->exists();}
public function provisionStudent(Request $r,int $student,CredentialService $c){abort_unless($this->canProvisionPerson($r,'student',$student),403);abort_if(User::where('student_id',$student)->exists(),422,'Учётная запись уже существует.');$s=DB::table('students')->find($student);abort_if(!$s,404);$role=Role::where('code','student')->firstOrFail();$plain=$c->password();$login=$c->login($s->last_name,$s->first_name,$s->id);$u=User::create($c->pack($plain)+['name'=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name),'login'=>$login,'email'=>$login.'@students.local','student_id'=>$s->id,'is_active'=>true]);$u->roles()->syncWithoutDetaching([$role->id]);return back()->with('success','Учётная запись студента создана.')->with('created_credentials',[['name'=>$u->name,'login'=>$login,'password'=>$plain,'type'=>'Студент']]);}
public function provisionTeacher(Request $r,int $teacher,CredentialService $c){abort_unless($this->canProvisionPerson($r,'teacher',$teacher),403);abort_if(User::where('teacher_id',$teacher)->exists(),422,'Учётная запись уже существует.');$t=DB::table('teachers')->find($teacher);abort_if(!$t,404);$role=Role::where('code','teacher')->firstOrFail();$plain=$c->password();$login=$c->login($t->last_name,$t->first_name,$t->id);$u=User::create($c->pack($plain)+['name'=>trim($t->last_name.' '.$t->first_name.' '.$t->middle_name),'login'=>$login,'email'=>$login.'@teachers.local','teacher_id'=>$t->id,'is_active'=>true]);$u->roles()->syncWithoutDetaching([$role->id]);return back()->with('success','Учётная запись преподавателя создана.')->with('created_credentials',[['name'=>$u->name,'login'=>$login,'password'=>$plain,'type'=>'Преподаватель']]);}
public function provisionMissingTeachers(Request $r,CredentialService $c){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic'),403);$role=Role::where('code','teacher')->firstOrFail();$credentials=[];$teachers=DB::table('teachers as t')->leftJoin('users as u','u.teacher_id','=','t.id')->where('t.active',1)->whereNull('u.id')->select('t.*')->get();foreach($teachers as $t){$plain=$c->password();$login=$c->login($t->last_name,$t->first_name,$t->id);$u=User::create($c->pack($plain)+['name'=>trim($t->last_name.' '.$t->first_name.' '.$t->middle_name),'login'=>$login,'email'=>$login.'@teachers.local','teacher_id'=>$t->id,'is_active'=>true]);$u->roles()->syncWithoutDetaching([$role->id]);$credentials[]=['name'=>$u->name,'login'=>$login,'password'=>$plain,'type'=>'Преподаватель'];}return back()->with('success','Создано недостающих учётных записей преподавателей: '.count($credentials))->with('created_credentials',$credentials);}
public function reset(Request $r,User $user,CredentialService $c){abort_unless($this->canReset($r,$user),403);$plain=$c->password();$user->update($c->pack($plain));return back()->with('success','Новый временный пароль создан для '.$user->name)->with('created_credentials',[['name'=>$user->name,'login'=>$user->login?:$user->email,'password'=>$plain,'type'=>$user->teacher_id?'Преподаватель':'Студент']]);}
public function print(Request $r,CredentialService $c){$this->view($r);$gid=$r->validate(['group'=>'required|exists:study_groups,id'])['group'];$group=DB::table('study_groups')->find($gid);$users=User::whereIn('student_id',DB::table('students')->where('current_group_id',$gid)->pluck('id'))->orderBy('name')->get();foreach($users as $u)$u->plain_password=$c->reveal($u->password_encrypted);return view('admin.credentials.print',compact('group','users'));}
}